/**
 * The languages of GitHub whose name a fence can hold, from linguist's languages.yml
 * (https://github.com/github-linguist/linguist). GitHub reads the word after an opening fence with this list,
 * so the picker and the name under the code use it. Each row is the name that the picker shows, the word for
 * the fence, and the other words for that language. A language whose name has spaces uses an alias that has none.
 * Generated file. Do not edit by hand; a language that changes in linguist needs the same change here.
 */
export type LanguageRow = [name: string, id: string, ...aliases: string[]];

